[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    // From route parameter
    [HttpGet("{id}")]
    public IActionResult Get([FromRoute] int id) => Ok(id);

    // From query string: /orders?status=pending&page=1
    [HttpGet("search")]
    public IActionResult Search(
        [FromQuery] string status,
        [FromQuery] int page = 1) => Ok((status, page));

    // From request body (JSON)
    [HttpPost]
    public IActionResult Create([FromBody] CreateOrderRequest request)
        => Created("", request);

    // From header
    [HttpGet("trace")]
    public IActionResult Trace([FromHeader(Name = "X-Correlation-ID")] string correlationId)
        => Ok(correlationId);
}

public class CommaSeparatedModelBinder : IModelBinder
{
    public Task BindModelAsync(ModelBindingContext context)
    {
        var value = context.ValueProvider.GetValue(context.ModelName).ToString();
        var items = value?.Split(',', StringSplitOptions.RemoveEmptyEntries)
                         .Select(s => s.Trim())
                         .ToArray() ?? Array.Empty<string>();
        context.Result = ModelBindingResult.Success(items);
        return Task.CompletedTask;
    }
}

[ModelBinder(BinderType = typeof(CommaSeparatedModelBinder))]
public string[] Tags { get; set; }

// Usage: POST /api/posts { "title": "A", "Tags": "csharp, aspnet, mvc" }
